svg.script:
'use strict';
const $=id=>document.getElementById(id), NS='http://www.w3.org/2000/svg';
const colors={bg:'#0c0e15',surface:'#171b26',raised:'#242a39',ice:'#b4c9ff',mint:'#9de3cf'};
const initialItems=[{id:1,title:'Good ideas deserve a place.',text:'Good ideas deserve a place. Keep them close.',collection:'Ideas',type:'note'}, {id:2,title:'Designing for the everyday',text:'https://developer.android.com/design?utm_source=sample',collection:'Reading',type:'link'}, {id:3,title:'A small moment of inspiration',text:'Sample image cutout',collection:'Inbox',type:'image'}];
let state={screen:'home',page:0,dockPage:0,bubble:false,bubbleX:338,bubbleY:420,access:false,notifications:false,shizuku:false,captureAccess:false,google:true,assistant:false,auto:false,haptics:true,strips:true,swipe:true,corners:false,hold:false,double:false,bounce:1,filter:'All',selected:[],items:initialItems.map(x=>({...x})),modal:null,captured:false,crop:false,points:[],dragging:false,gesture:false};
let holdTimer,toastTimer,sequence=10,down=null,lastTap=0;
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));}
function rect(x,y,w,h,fill=colors.surface,r=20,extra=''){return `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${r}" fill="${fill}" ${extra}/>`;}
function txt(x,y,s,cls='body',extra=''){return `<text x="${x}" y="${y}" class="${cls}" ${extra}>${esc(s)}</text>`;}
function icon(name,x,y,size=22,color=colors.ice){return `<use href="#i-${name}" x="${x}" y="${y}" width="${size}" height="${size}" style="color:${color}"/>`;}
function action(id,label,body){const r=body.match(/^<rect x="([\d.]+)" y="([\d.]+)" width="([\d.]+)" height="([\d.]+)"/);if(r){const [x,y,w,h]=r.slice(1).map(Number);if(w<48||h<48)body=rect(x-Math.max(0,48-w)/2,y-Math.max(0,48-h)/2,Math.max(w,48),Math.max(h,48),"transparent",12)+body;}return `<g class="btn" role="button" tabindex="0" data-action="${esc(id)}" aria-label="${esc(label)}">${body}</g>`;}
function button(x,y,w,label,id,primary=false,ico=''){return action(id,label,rect(x,y,w,48,primary?colors.ice:colors.raised,16)+ (ico?icon(ico,x+14,y+13,21,primary?'#16213a':colors.ice):'')+txt(ico?x+46:x+w/2,y+29,label,'body',`text-anchor="${ico?'start':'middle'}" style="fill:${primary?'#14203b':'#eaf0ff'};font-weight:600"`));}
function chromeHeader(title,subtitle,back=false){return txt(22,33,'9:41','small', 'font-weight="700"')+txt(368,33,'LTE  ▰','small','text-anchor="end"')+(back?action('back','Back',rect(13,56,44,44,colors.bg,13)+icon('back',24,67)):'')+txt(back?64:22,82,title,'caps')+txt(368,82,'UI CONCEPT','small muted','text-anchor="end"')+(subtitle?txt(22,119,subtitle,'headline'):'');}
function nav(){return rect(0,758,390,86,colors.bg,0)+`<path d="M20 758H370" stroke="#252a39"/>`+['home','shelf','settings'].map((s,i)=>action('nav:'+s,s,rect(21+i*125,770,98,51,state.screen===s?colors.raised:colors.bg,17)+icon(['home','stack','settings'][i],35+i*125,783,21,state.screen===s?colors.ice:'#8c94a9')+txt(63+i*125,798,['Home','Shelf','Settings'][i],'small',state.screen===s?'fill="#b4c9ff"':''))).join('')+rect(144,831,102,4,'#626a7e',2);}
function section(y,title,right=''){return txt(22,y,title,'title')+(right?txt(368,y,right,'small muted','text-anchor="end"'):'');}
function itemCard(item,y,compact=false){const chosen=state.selected.includes(item.id),h=compact?77:91;return action('item:'+item.id,'Select '+item.title,rect(22,y,346,h,chosen?'#283249':colors.surface,20,chosen?'stroke="#b4c9ff"':'')+rect(36,y+17,42,42,chosen?'#3e5170':colors.raised,13)+icon(chosen?'check':item.type==='link'?'link':item.type==='image'?'image':'note',46,y+27,22)+txt(91,y+30,item.title.length>29?item.title.slice(0,27)+'…':item.title,'body')+txt(91,y+51,item.collection,'small ice')+icon('arrow',335,y+27,18));}
function bubble(){if(!state.bubble||!['home','shelf','settings','preferences'].includes(state.screen))return '';return `<g id="bubble" role="button" tabindex="0" aria-label="Floating bubble: tap shelf, hold search, drag to move or dismiss" transform="translate(${state.bubbleX} ${state.bubbleY})"><circle r="30" fill="url(#glass)" stroke="#8eacc4" stroke-width="1.4" filter="url(#shadow)"/>${icon('stack',-13,-13,26)}<circle cx="21" cy="-22" r="10" fill="#9de3cf"/>${txt(21,-18,state.items.length,'small','text-anchor="middle" style="fill:#102c28;font-weight:700"')}</g>`;}
function home(){return chromeHeader('STASHDROP','Everything within reach.')+txt(22,146,'Catch an idea. Keep it close.','body muted')+rect(22,173,346,210,colors.surface,28)+`<circle cx="195" cy="260" r="96" fill="url(#halo)"/>`+rect(143,207,104,90,'url(#glass)',29,'stroke="#55617d" transform="rotate(-7 195 252)"')+icon('stack',175,233,40)+txt(195,326,'A little space. For everything.','body','text-anchor="middle"')+txt(195,350,state.bubble?'Bubble active · hold it to search':'Start with your floating shelf','small muted','text-anchor="middle"')+button(22,401,346,state.bubble?'Hide floating bubble':state.access?'Show floating bubble':'Allow floating bubble','bubble-toggle',true,'stack')+action('search','Circle to Search',rect(22,464,346,75)+icon('circle',38,488,25)+txt(81,492,'Circle to Search','title')+txt(81,513,state.google?'Google route · switch in Settings':'Built-in · circle, copy, save','small muted')+icon('arrow',335,490,18))+action('nav:settings','Setup and connections',rect(22,550,346,68)+icon('settings',39,572,24)+txt(81,579,'Setup & connections','title')+txt(81,598,state.access?'Review access and integrations':'A few permissions, at your pace','small muted')+icon('arrow',335,576,18))+section(650,'Recent',state.items.length+' saved')+(state.items[0]?itemCard(state.items[0],665,true):txt(22,700,'Your next good idea goes here.','body muted'))+nav();}
function shelf(){const all=['All',...new Set(state.items.map(x=>x.collection))],items=state.items.filter(i=>state.filter==='All'||i.collection===state.filter);state.page=Math.min(state.page,Math.max(0,Math.ceil(items.length/3)-1));return chromeHeader('YOUR SPACE','Your shelf.')+action('note','Add note',rect(274,96,94,43,colors.ice,15)+icon('plus',284,108,18,'#15223e')+txt(310,123,'Note','body','style="fill:#15223e;font-weight:600"'))+txt(22,149,state.items.length+' saved · tap a card to select','body muted')+all.slice(0,4).map((c,i)=>action('filter:'+c,'Filter '+c,rect(22+i*87,171,80,35,state.filter===c?'#354261':colors.surface,17)+txt(62+i*87,193,c,'small',`text-anchor="middle" style="fill:${state.filter===c?colors.ice:'#b1b6c5'}"`))).join('')+items.slice(state.page*3,state.page*3+3).map((item,i)=>itemCard(item,224+i*103)).join('')+pager(548,items.length,'page',state.page)+(items.length===0?txt(195,340,'Nothing saved here yet.','body muted','text-anchor="middle"'):'')+button(22,668,346,'Share something into StashDrop','import',false,'plus')+(state.selected.length?rect(14,595,362,62,'#303d57',19)+txt(29,621,state.selected.length+' selected','small')+button(122,602,106,'Share','share',true)+button(236,602,130,'More actions','selected-menu'):txt(22,646,'Hold cards in the floating shelf to drag.','small muted'))+nav();}
function row(y,label,detail,id,kind='arrow',value=false){return action(id,label,rect(22,y,346,63)+txt(38,y+25,label,'body')+txt(38,y+44,detail,'small muted')+(kind==='switch'?rect(305,y+19,45,26,value?colors.ice:'#41495b',13)+`<circle cx="${value?337:318}" cy="${y+32}" r="9" fill="${value?'#182a48':'#ccd2df'}"/>`:kind==='status'?txt(348,y+34,value?'On':'Allow','small '+(value?'mint':'ice'),'text-anchor="end"'):icon('arrow',329,y+23,18)));}
function settings(){return chromeHeader('MAKE IT YOURS','Settings.')+section(164,'Setup','Simulated permissions')+row(180,'Floating bubble','Display over other apps','permission:access','status',state.access)+row(250,'Notifications','Service controls and search action','permission:notifications','status',state.notifications)+row(320,'Shizuku',state.shizuku?'Authorized bridge connected':'Optional privileged shortcuts','permission:shizuku','status',state.shizuku)+row(390,'Screenshot access','Accessibility screenshot · Android 11+','permission:captureAccess','status',state.captureAccess)+section(488,'Search & assistant')+row(505,'Use Google Circle to Search',state.google?'Google decides device eligibility':'Built-in capture and on-device OCR','toggle:google','switch',state.google)+row(575,'Digital assistant',state.assistant?'StashDrop selected':'System picker / optional Shizuku','assistant')+row(645,'Gestures, clipboard & feel','Customize interactions and motion','nav:preferences')+nav();}
function preferences(){return chromeHeader('INTERACTIONS','Your way.',true)+txt(22,146,'Gesture strips run with the floating bubble.','small muted')+row(163,'Gesture strips','Bottom-edge overlay touch zones','toggle:strips','switch',state.strips)+row(232,'Swipe up','Pull 64 dp or flick to search','toggle:swipe','switch',state.swipe)+row(301,'Corner swipe','Pull inward from either corner','toggle:corners','switch',state.corners)+row(370,'Press and hold','Hold the bottom strip for 400 ms','toggle:hold','switch',state.hold)+row(439,'Double tap','Two taps within 300 ms','toggle:double','switch',state.double)+row(508,'Auto-stash copied text','Off by default · may retain sensitive text','toggle:auto','switch',state.auto)+row(577,'Haptic feedback','A tactile cue for each interaction','toggle:haptics','switch',state.haptics)+rect(22,646,346,77)+txt(38,671,'Springiness','body')+txt(348,671,state.bounce.toFixed(1)+'×','small ice','text-anchor="end"')+`<foreignObject x="37" y="675" width="315" height="44"><input xmlns="http://www.w3.org/1999/xhtml" id="spring" type="range" min="0.5" max="1.5" step="0.1" value="${state.bounce}" aria-label="Springiness"/></foreignObject>`+action('nav:settings','Back to Settings',rect(22,737,346,47,colors.raised,16)+txt(195,766,'Back to Settings','body','text-anchor="middle"'))+rect(144,831,102,4,'#626a7e',2);}
function pager(y,total,key,index,size=3){if(total<=size)return '';return action('previous:'+key,'Previous cards',rect(22,y,52,36,colors.raised,13)+icon('back',38,y+8,20))+txt(195,y+23,(index+1)+' / '+Math.ceil(total/size),'small muted','text-anchor="middle"')+action('next:'+key,'Next cards',rect(316,y,52,36,colors.raised,13)+icon('arrow',332,y+8,20));}
function dock(){return chromeHeader('FLOATING SHELF','Close to your thumb.',true)+txt(22,149,'Sample foreground app','small muted')+rect(22,176,346,216,'#151e29',25)+txt(45,217,'A good thought can','headline')+txt(45,254,'arrive anywhere.','headline')+txt(45,291,'Keep it without losing your place.','body muted')+rect(0,353,390,491,colors.surface,29,'filter="url(#shadow)"')+rect(170,366,50,4,'#626a7e',2)+txt(22,405,'Your shelf','headline')+txt(22,427,'Tap cards to select','small muted')+action('search','Circle to Search',rect(310,384,48,48,colors.raised,16)+icon('circle',323,397))+action('nav:home','Close floating shelf',rect(352,350,34,34,colors.raised,17)+icon('close',360,358,18))+state.items.slice(state.dockPage*2,state.dockPage*2+2).map((it,i)=>itemCard(it,449+i*87,true)).join('')+pager(636,state.items.length,'dockPage',state.dockPage,2)+ (state.selected.length? `<g id="drag-stack" tabindex="0" role="button" aria-label="Drag selected cards to sample drop target">${rect(27,723,80,65,'#384b6c',13,'transform="rotate(-5 67 755)"')}${rect(32,718,80,65,'#455b7c',13)}${icon('stack',56,735,26)}${txt(83,738,state.selected.length,'small')}</g>`+button(126,725,112,'WhatsApp','whatsapp',true)+button(247,725,121,'Share','share')+txt(195,809,'Drag the stack upward to the sample app','small muted','text-anchor="middle"'):button(22,733,346,'Select cards to share together','select-all',true));}
function capture(){return chromeHeader('BUILT-IN CIRCLE','Circle something useful.',true)+txt(22,147,state.crop?'Selection ready · recognition complete':'Draw a loop around the sample text','small muted')+rect(22,170,346,435,'#e8e5de',24)+txt(45,208,'FIELD NOTES','caps','style="fill:#66665d"')+txt(45,261,'Keep the things','headline','style="fill:#20362f"')+txt(45,299,'that move you.','headline','style="fill:#20362f"')+txt(45,341,'A thought. A link. A tiny discovery.','body','style="fill:#495c51"')+txt(45,364,'Give your next idea a place to land.','body','style="fill:#495c51"')+`<path d="M45 415H345M45 440H323M45 465H339" stroke="#b8bcb0" stroke-width="8" stroke-linecap="round"/>`+rect(45,507,300,66,'#d7ddce',14)+txt(61,534,'A little space. For everything.','body','style="fill:#355246"')+txt(61,555,'Sample content · no device capture','small','style="fill:#53675d"')+`<rect id="lasso-surface" x="22" y="170" width="346" height="435" rx="24" fill="transparent" style="touch-action:none;cursor:crosshair"/><path id="lasso-path" d="${state.crop?'M40 235 Q180 195 349 233 Q384 290 342 325 Q177 344 39 317 Q11 277 40 235Z':''}" fill="#b4c9ff22" stroke="url(#aurora)" stroke-width="3" class="lasso" pointer-events="none"/>`+ (state.crop?rect(22,621,346,56)+txt(38,644,'Keep the things that move you.','body')+txt(38,663,'Latin OCR · sample result, on device in app','small mint')+['Search','Lens','Copy','Stash','Share'].map((label,i)=>action('result:'+label.toLowerCase(),label,rect(22+i*70,694,66,47,i===3?colors.ice:colors.raised,15)+txt(55+i*70,723,label,'small',`text-anchor="middle" style="fill:${i===3?'#15223e':'#eaf0ff'}"`))).join('')+button(22,756,346,'Circle again','again'):button(22,633,346,'Select sample region','select-sample',true)+txt(195,715,'Capture is simulated in this design.','small muted','text-anchor="middle"')+txt(195,736,'Protected content remains protected.','small muted','text-anchor="middle"'));}
function native(){return chromeHeader('GOOGLE HAND-OFF','A different kind of search.',true)+`<circle cx="195" cy="286" r="103" fill="url(#halo)"/>`+icon('circle',159,250,72)+txt(195,428,'Native Google request','title','text-anchor="middle"')+txt(195,458,'The Android app requests Google’s UI.','body muted','text-anchor="middle"')+txt(195,481,'Google decides eligibility and appearance.','small muted','text-anchor="middle"')+rect(22,524,346,78)+txt(39,553,'Prototype simulation','body mint')+txt(39,578,'No Google session or screenshot is started.','small muted')+button(22,637,346,'Try the built-in circle instead','force-built-in',true)+button(22,701,346,'Return to Home','nav:home');}
function render(){const pages={home,shelf,settings,preferences,dock,capture,native};$('scene').innerHTML=`<g class="enter">${(pages[state.screen]||home)()}</g>`+bubble()+(state.bubble&&state.strips&&['home','shelf','settings'].includes(state.screen)?`<rect id="gesture-strip" x="85" y="820" width="220" height="22" rx="11" fill="#b4c9ff" fill-opacity=".13" style="touch-action:none"/>`:'');document.querySelectorAll('[data-action^="toggle:"]').forEach(el=>{el.setAttribute('role','switch');el.setAttribute('aria-checked',String(state[el.dataset.action.split(':')[1]]));});renderModal();expose();}
function announce(message){clearTimeout(toastTimer);$('toast').innerHTML=rect(30,35,330,45,'#34435a',16,'filter="url(#shadow)"')+txt(195,63,message.slice(0,47),'small','text-anchor="middle"');toastTimer=setTimeout(()=>$('toast').innerHTML='',2600);event('feedback',message);}
function event(action,detail=''){try{window.parent.postMessage({type:'stashdrop-design',action,detail,screen:state.screen},'*')}catch{}}
function go(screen){state.page=0;state.dockPage=0;state.screen=screen;state.modal=null;state.selected=[];render();event('navigate',screen);}
function modal(title,lines,buttons,body=''){const h=170+lines.length*22+(body?110:0)+buttons.length*56,y=(844-h)/2;return `<rect width="390" height="844" fill="#000" opacity=".65" data-action="cancel"/>`+rect(20,y,350,h,colors.surface,27,'filter="url(#shadow)"')+txt(42,y+39,title,'title')+lines.map((l,i)=>txt(42,y+72+i*22,l,'small muted')).join('')+(body?`<foreignObject x="42" y="${y+83+lines.length*22}" width="306" height="96"><textarea xmlns="http://www.w3.org/1999/xhtml" id="note-text" aria-label="Note text" placeholder="Write a thought or paste a link…">${esc(state.noteDraft||'')}</textarea></foreignObject>`:'')+buttons.map((b,i)=>button(42,y+h-25-(buttons.length-i)*56,306,b[0],b[1],i===0)).join('');}
function renderModal(){let m=state.modal,html='';if(m){if(m.type==='permission')html=modal('Allow '+m.label+'?',['This is a simulated Android access screen.','Your device settings are not changed.'],[['Allow in prototype','grant:'+m.key],['Not now','cancel']]);if(m.type==='note')html=modal('Keep a thought',['Saved locally in the Android app.'],[['Save note','save-note'],['Cancel','cancel']],true);if(m.type==='share')html=modal(m.whatsapp?'Send to WhatsApp':'Share selection',[m.count+' item(s) prepared with temporary access.','A real receiver decides supported formats.'],[['Simulate successful share','share-success'],['Cancel','cancel']]);if(m.type==='more')html=modal('Selection actions',[state.selected.length+' item(s) selected.'],[['Move to Ideas','move:Ideas'],['New collection…','collection'],['Delete selected','delete-confirm'],['Cancel','cancel']]);if(m.type==='collection')html=modal('Move to collection',['Use a name, or leave blank for Inbox.'],[['Move selected','save-collection'],['Cancel','cancel']],true).replace(/<textarea[^>]*>[\s\S]*?<\/textarea>/, '<input xmlns="http://www.w3.org/1999/xhtml" id="collection-name" type="text" aria-label="Collection name" maxlength="80" placeholder="Collection name" style="height:48px;background:#242a39;color:#f1f3fa;border:1px solid #697895;border-radius:12px;padding:12px;box-sizing:border-box"/>');if(m.type==='crash')html=modal('StashDrop closed unexpectedly',['Sample report · no personal data','Overlay session ended unexpectedly.','App 0.3.2 · Android 15 · simulated'],[['Copy sample report','copy-crash'],['Dismiss','cancel']]);if(m.type==='delete')html=modal('Delete selected items?',['The Android app deletes cached files too.','There is currently no trash or restore.'],[['Delete permanently','delete'],['Keep items','cancel']]);if(m.type==='import')html=modal('Share into StashDrop',['Demo: import a link with tracking parameters.','The app accepts readable files up to 50 MB.'],[['Import sample clean link','import-link'],['Import sample image','import-image'],['Cancel','cancel']]);if(m.type==='capture')html=modal('Share your screen?',['Simulated MediaProjection consent.','The app needs capture access for the lasso.'],[['Allow sample capture','capture-allow'],['Not now','cancel']]);if(m.type==='assistant')html=modal('Digital assistant',[state.assistant?'StashDrop receives assistant gestures.':'Choose a simulated assistant route.','Shizuku Connect keeps Google voice active.'],[['Use StashDrop','assistant-select'],['Connect Google via Shizuku','assistant-connect'],['Restore previous assistant','assistant-restore'],['Cancel','cancel']]);if(m.type==='external')html=modal(m.label,['This action leaves StashDrop in the app.','No external app opens in this prototype.'],[['Return to selection','cancel']]);if(m.type==='clipboard')html=modal('Save copied text?',['Can retain passwords, codes or private text.','Earlier items remain when turned off.'],[['Enable auto-stash','enable-auto'],['Keep it off','cancel']]);} $('overlay').innerHTML=html;}
function saveCrop(){if(!state.savedCrop){let item={id:++sequence,title:'Keep the things that move you.',text:'Selected image cutout',collection:'Inbox',type:'image'};state.items.unshift(item);state.savedCrop=item.id;}}
function search(force=false){state.crop=false;state.savedCrop=null;if(state.google&&!force){go('native');return;}if(state.shizuku||state.captureAccess||state.captured){go('capture')}else{state.modal={type:'capture'};renderModal();}event('search',force?'built-in':state.google?'google':'built-in');}
function handle(id){if(!id)return;event('action',id);let [type,key]=id.split(':');if(type==='nav'){go(key);return;}if(type==='next'||type==='previous'){const total=key==='page'?state.items.filter(i=>state.filter==='All'||i.collection===state.filter).length:state.items.length;state[key]=Math.max(0,Math.min(Math.ceil(total/(key==='page'?3:2))-1,state[key]+(type==='next'?1:-1)));render();return;}if(type==='filter'){state.page=0;state.filter=key;state.selected=[];render();return;}if(type==='item'){if(state.screen==='home')state.screen='shelf';state.selected=state.selected.includes(+key)?state.selected.filter(x=>x!==+key):[...state.selected,+key];render();return;}if(type==='toggle'){if(key==='auto'&&!state.auto){state.modal={type:'clipboard'};renderModal();return;}state[key]=!state[key];render();announce(key+' '+(state[key]?'on':'off'));return;}if(type==='permission'){state.modal={type:'permission',key,label:{access:'floating bubble',notifications:'notifications',shizuku:'Shizuku',captureAccess:'screenshot access'}[key]};renderModal();return;}if(type==='grant'){state[key]=true;state.modal=null;render();announce('Simulated access enabled');return;}if(type==='move'){state.items.forEach(i=>{if(state.selected.includes(i.id))i.collection=key});state.selected=[];state.filter='All';state.modal=null;render();announce('Moved to '+key);return;}if(type==='result'){if(['stash','lens','share'].includes(key))saveCrop();if(key==='stash'){render();announce('Cutout saved to your shelf');}if(key==='copy')announce('Demo text copied within prototype');if(key==='search'||key==='lens'){state.modal={type:'external',label:key==='search'?'Search recognized text':'Search cutout with Lens'};renderModal();}if(key==='share'){state.modal={type:'share',count:1};renderModal();}return;}
switch(id){case 'back':go(state.screen==='preferences'?'settings':'home');break;case 'bubble-toggle':if(!state.access){handle('permission:access');break;}state.bubble=!state.bubble;render();announce(state.bubble?'Bubble ready · tap, hold or drag':'Bubble hidden');break;case 'search':search();break;case 'force-built-in':search(true);break;case 'capture-allow':state.captured=true;go('capture');break;case 'select-sample':state.crop=true;render();announce('Sample text recognized');break;case 'again':state.crop=false;state.savedCrop=null;render();break;case 'note':state.noteDraft='';state.modal={type:'note'};renderModal();break;case 'save-note':{const value=$('note-text').value.trim();if(!value){announce('Write something before saving');return;}const clean=value.replace(/([?&])utm_[^=&]+=[^&#\s]*&?/g,'$1').replace(/[?&]$/,'');state.items.unshift({id:++sequence,title:clean.split('\n')[0].slice(0,80),text:clean,collection:'Inbox',type:clean.startsWith('http')?'link':'note'});state.modal=null;state.filter='All';render();announce('Note saved to Inbox');break;}case 'import':state.modal={type:'import'};renderModal();break;case 'import-link':state.items.unshift({id:++sequence,title:'developer.android.com/design',text:'https://developer.android.com/design',collection:'Inbox',type:'link'});state.modal=null;state.filter='All';render();announce('Link saved · tracking parameter removed');break;case 'import-image':state.items.unshift({id:++sequence,title:'Shared sample image',text:'Sample imported attachment',collection:'Inbox',type:'image'});state.modal=null;state.filter='All';render();announce('Sample image imported');break;case 'collection':state.modal={type:'collection'};renderModal();break;case 'save-collection':{const name=$('collection-name').value.trim().slice(0,80)||'Inbox';state.items.forEach(i=>{if(state.selected.includes(i.id))i.collection=name});state.selected=[];state.filter='All';state.page=0;state.modal=null;render();announce('Moved to '+name);break;}case 'show-crash':state.modal={type:'crash'};renderModal();break;case 'copy-crash':announce('Sample report copied · simulated');break;case 'selected-menu':state.modal={type:'more'};renderModal();break;case 'delete-confirm':state.modal={type:'delete'};renderModal();break;case 'delete':state.items=state.items.filter(x=>!state.selected.includes(x.id));state.selected=[];state.modal=null;render();announce('Selected items deleted');break;case 'select-all':state.selected=state.items.map(i=>i.id);render();break;case 'share':case 'whatsapp':if(!state.selected.length){announce('Select one or more cards first');break;}state.modal={type:'share',count:state.selected.length,whatsapp:id==='whatsapp'};renderModal();break;case 'share-success':state.modal=null;state.selected=[];render();announce('Share completed · prototype simulation');break;case 'assistant':state.modal={type:'assistant'};renderModal();break;case 'assistant-select':state.assistant=true;state.modal=null;render();announce('StashDrop selected · simulated');break;case 'assistant-connect':if(!state.shizuku){announce('Connect Shizuku in Setup first');return;}state.assistant=true;state.google=true;state.modal=null;render();announce('Google voice service linked · simulated');break;case 'assistant-restore':state.assistant=false;state.modal=null;render();announce('Previous assistant restored · simulated');break;case 'enable-auto':state.auto=true;state.modal=null;render();announce('Auto-stash enabled · simulated');break;case 'cancel':state.modal=null;renderModal();break;}
expose();}
function expose(){window.stashdropDesign={getState:()=>JSON.parse(JSON.stringify(state)),navigate:go,action:handle,reset:()=>{clearTimeout(holdTimer);clearTimeout(toastTimer);down=null;$('toast').innerHTML='';state.bubbleX=338;state.bubbleY=420;state.noteDraft='';state.savedCrop=null;state.points=[];state.items=initialItems.map(x=>({...x}));state.selected=[];state.filter='All';state.modal=null;state.bubble=false;state.access=false;state.notifications=false;state.shizuku=false;state.captureAccess=false;state.google=true;state.assistant=false;state.auto=false;state.haptics=true;state.strips=true;state.swipe=true;state.corners=false;state.hold=false;state.double=false;state.bounce=1;state.captured=false;state.crop=false;go('home');},scene:()=> $('scene').innerHTML};}
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(a)handle(a.dataset.action);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(state.modal)handle('cancel');else if(state.screen!=='home')go('home');}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-action]')){e.preventDefault();handle(e.target.dataset.action);}if((e.key==='Enter'||e.key===' ')&&e.target.id==='drag-stack'){e.preventDefault();announce('Sample drop accepted · simulated');event('global-drag','keyboard simulated drop');}if((e.key==='Enter'||e.key===' ')&&e.target.id==='bubble'){e.preventDefault();go('dock');}});
document.addEventListener('input',e=>{if(e.target.id==='spring'){state.bounce=+e.target.value;event('springiness',state.bounce);const texts=$('scene').querySelectorAll('text');texts.forEach(t=>{if(t.textContent.endsWith('×'))t.textContent=state.bounce.toFixed(1)+'×'});}if(e.target.id==='note-text')state.noteDraft=e.target.value;});
function point(e){let p=document.documentElement.createSVGPoint();p.x=e.clientX;p.y=e.clientY;return p.matrixTransform(document.documentElement.getScreenCTM().inverse());}
document.addEventListener('pointerdown',e=>{const p=point(e),target=e.target.closest('#bubble,#lasso-surface,#gesture-strip,#drag-stack');if(!target||state.modal)return;down={kind:target.id,x:p.x,y:p.y,bx:state.bubbleX,by:state.bubbleY,time:Date.now(),moved:false,held:false};try{target.setPointerCapture(e.pointerId)}catch{}if(target.id==='bubble'){holdTimer=setTimeout(()=>{if(down&&!down.moved){down.held=true;search()}},500);}if(target.id==='lasso-surface'){state.points=[[p.x,p.y]];}if(target.id==='gesture-strip'&&state.hold)holdTimer=setTimeout(()=>{if(down&&!down.moved){down.held=true;search()}},400);});
document.addEventListener('pointermove',e=>{if(!down)return;const p=point(e),dx=p.x-down.x,dy=p.y-down.y;if(Math.hypot(dx,dy)>8){down.moved=true;clearTimeout(holdTimer);}if(down.kind==='bubble'&&down.moved){state.bubbleX=Math.max(32,Math.min(358,down.bx+dx));state.bubbleY=Math.max(160,Math.min(790,down.by+dy));$('bubble')?.setAttribute('transform',`translate(${state.bubbleX} ${state.bubbleY})`);if(!$('dismiss-target'))$('overlay').innerHTML=`<g id="dismiss-target">${rect(155,733,80,70,'#6b344c',28)}${icon('close',180,755,30,'#ffbdcf')}</g>`;}if(down.kind==='lasso-surface'){state.points.push([p.x,p.y]);$('lasso-path').setAttribute('d',state.points.map((v,i)=>(i?'L':'M')+v.join(' ')).join(' '));}if(down.kind==='drag-stack'){e.target.closest('#drag-stack')?.setAttribute('transform',`translate(${dx} ${dy})`);}});
document.addEventListener('pointerup',e=>{if(!down)return;clearTimeout(holdTimer);const p=point(e),d=down;down=null;if(d.kind==='bubble'){if(d.held)return;if(d.moved){if(p.y>725&&p.x>135&&p.x<255){state.bubble=false;render();announce('Bubble dismissed · shelf kept');}else{state.bubbleX=p.x<195?32:358;state.bubbleY=Math.min(703,state.bubbleY);render();announce('Bubble snapped to edge');}}else go('dock');}if(d.kind==='lasso-surface'&&state.points.length>4&&d.moved){state.crop=true;render();announce('Sample text recognized');}if(d.kind==='drag-stack'){render();announce(p.y<390?'Sample drop accepted · simulated':'Drag canceled · try the sample app');event('global-drag',p.y<390?'accepted simulation':'canceled');}if(d.kind==='gesture-strip'&&!d.held){let up=d.y-p.y,corner=(d.x<135||d.x>255),inward=corner&&((d.x<135&&p.x>d.x)||(d.x>255&&p.x<d.x));if((state.swipe&&up>64)||(state.corners&&up>35&&inward))search();else if(!d.moved&&state.double){if(Date.now()-lastTap<300)search();lastTap=Date.now();}}});
document.addEventListener('pointercancel',()=>{clearTimeout(holdTimer);down=null;$('overlay').innerHTML='';renderModal();});
window.addEventListener('message',e=>{if(e.data?.type==='stashdrop-control'){if(e.data.action==='reset')window.stashdropDesign.reset();else if(e.data.action==='navigate')go(e.data.screen);else if(e.data.action==='search')search(true);else if(e.data.action==='crash')handle('show-crash');}});
render();
